window.AUTH=window.AUTH||{};window.AUTH["19-7"]={"d":"19-7","id":"2019/19-7","n":"Seila Law LLC v. Consumer Financial Protection Bureau","briefs":[{"k":"petitioner","label":"Brief of petitioner Seila Law LLC","date":"2019-12-09","url":"https://www.supremecourt.gov/DocketPDF/19/19-7/124949/20191209155012780_Seila%20Law%20brief%20for%20petitioner.pdf","side":"pet","n":85},{"k":"respondent","label":"Brief of respondent Consumer Financial Protection Bureau","date":"2019-12-09","url":"https://www.supremecourt.gov/DocketPDF/19/19-7/125006/20191209210939522_19-7tsUnitedStates-REVISED.pdf","side":"res","n":65},{"k":"united-states","label":"Brief amicus curiae of United States House of Representatives","date":"2020-01-22","url":"https://www.supremecourt.gov/DocketPDF/19/19-7/129452/20200122125542419_19-7bsacTheUnitedStatesHouseOfRepresentatives.pdf","side":"us","n":50},{"k":"reply","label":"Reply of petitioner Seila Law LLC","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/19/19-7/133091/20200214140648263_Seila%20reply%20brief%20of%20petitioner.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US1PP_web.pdf#page=207","tr":true,"items":[{"t":"case","label":"A.L.A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"op":16,"sum":"The Court held that the legislative branch cannot delegate to the President the authority to regulate industries without also providing standards or rules for doing so.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Alaska Airlines, Inc. v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"op":2,"sum":"Section 43(f)(3)'s legislative-veto provision is severable from the remainder of the EPP program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 42, 45, 46","1":"46"}},{"t":"case","label":"Ayotte v. Planned Parenthood of Northern New England","cite":"546 U.S. 320","y":2006,"id":"2005/04-1144","sc":1,"sum":"In a rare unanimous decision regarding abortion, the Supreme Court sidestepped the most contentious questions of the case and focused instead on the proper remedy when a portion of a statute is found unconstitutional.","sumSrc":"Oyez","by":{"0":"38","1":"46"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"op":11,"ar":5,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"0":"passim","1":"11, 14, 43","2":"passim","3":"6, 7, 18"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"ar":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"25, 43","1":"32","2":"14, 17"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"op":3,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"0":"16, 26, 30","1":"10, 30"}},{"t":"case","label":"Collins v. Mnuchin","cite":"938 F.3d 553","y":2019,"court":"filed Sept. 25","url":"https://www.courtlistener.com/c/F.3d/938/553/","op":1,"by":{"0":"24","1":"35"}},{"t":"case","label":"Colorado Republican Federal Campaign Committee v. FEC","cite":"518 U.S. 604","y":1996,"id":"1995/95-489","sc":1,"op":1,"sum":"Justice Stephen G. Breyer announced the judgment of the Court and authored an opinion, in which the Court ruled that the First Amendment prohibits the application of the Party Expenditure Provision of the Federal Election Campaign Act of 1971 (FECA) to the kind of expenditure at issue here-an expenditure that the political party has made independently, without coordination with any candidate.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"FEC v. NRA Political Victory Fund","cite":"6 F.3d 821","y":1993,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/6/821/","by":{"0":"36"}},{"t":"case","label":"Free Enterprise Fund v. Public Company Accounting Oversight Board","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":47,"ar":10,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"FTC v. Ruberoid Co.","cite":"343 U.S. 470","y":1952,"id":"scdb/1951-083","sc":1,"op":1,"sum":"A company which was engaged in the manufacture of roofing materials was found by the Federal Trade Commission to have discriminated among customers in the prices charged for its products. The Commission held that the discriminations violated 6 2 (a) of the Clayton Act, as amended, and ordered the company to cease and desist from selling \"products of like grade and quality to any purchaser at prices lower than those …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","3":"15"}},{"t":"case","label":"Hill v. Wallace","cite":"259 U.S. 44","y":1922,"id":"scdb/1921-138","sc":1,"sum":"1. Members of an incorporated board of trade have standing to maintain a bill against its president and directors to restrain them from complying with an unconstitutional act of Congress threatening seriously to impair the value of the board to its members and the value of their memberships, when the directors have refused to bring the suit for fear of antagonizing government officials.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Humphrey’s Executor v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"op":20,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"2, 10, 17, 18"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":2,"ar":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"15, 24","1":"31, 47","2":"5, 10","3":"4"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"Legal Services Corp. v. Velazquez","cite":"531 U.S. 533","y":2001,"id":"2000/99-603","sc":1,"sum":"The Court held that the funding provision that limited arguments legal services attorneys were allowed to make on behalf of indigent welfare claimants violated the First Amendment by regulating private speech and insulating federal law from legitimate judicial challenge.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Louisville Joint Stock Land Bank v. Radford","cite":"295 U.S. 555","y":1935,"id":"scdb/1934-071","sc":1,"op":16,"sum":"1. The bankruptcy power, like the other great substantive: powler§ of Congress, is subject to the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"ar":1,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"0":"36, 37","3":"19"}},{"t":"case","label":"Mitchell v. Helms","cite":"530 U.S. 793","y":2000,"id":"1999/98-1648","sc":1,"sum":"In a 6-3 plurality decision delivered by Justice Clarence Thomas, the Court held that that Chapter 2, as applied in Jefferson Parish, is not a law respecting an establishment of religion simply because many of the private schools receiving Chapter 2 aid in the parish are religiously affiliated.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"op":57,"ar":7,"sum":"Recognizing that limit as the constitutional standard.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"17, 20, 25","3":"2, 15"}},{"t":"case","label":"Murphy v. NCAA","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"op":10,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"18, 27","3":"passim"}},{"t":"case","label":"National Federation of Independent Business v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"42, 44"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"134 S. Ct. 2550","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2550/","sc":1,"by":{"0":"24"}},{"t":"case","label":"Noel Canning v. NLRB","cite":"705 F.3d 490","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/705/490/","by":{"0":"36"}},{"t":"case","label":"Northern Pipeline Construction Co. v. Marathon Pipe Line Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"0":"36","3":"7"}},{"t":"case","label":"PHH Corp. v. CFPB","cite":"881 F.3d 75","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/881/75/","op":4,"sum":"Observing that Humphrey’s Executor “appear[s] at odds with the text and original understanding of Article II”.","sumSrc":"brief:0","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"op":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"16, 39","1":"10, 30"}},{"t":"case","label":"Ryder v. United States","cite":"515 U.S. 177","y":1995,"id":"1994/94-431","sc":1,"sum":"The Court held that the judges' actions were not valid de facto. The Court reasoned that a defendant who made a timely challenge to the constitutional validity of the appointment of an officer who adjudicates his case was entitled to a decision on the merits of the question and whatever relief may be appropriate if a violation had occurred.","sumSrc":"Oyez","by":{"0":"35, 36"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"op":1,"sum":"The Court held that the Bankruptcy Court did not have the constitutional authority to enter judgement on the petitioner's counterclaim.","sumSrc":"Oyez","by":{"0":"36, 38"}},{"t":"case","label":"United States v. Jackson","cite":"390 U.S. 570","y":1968,"id":"1967/85","sc":1,"sum":"The death penalty clause imposes an impermissible burden upon the exercise of a constitutional right, but that provision is severable from the remainder of the Act and the unconstitutionality of that clause does not require the defeat of the Act as a whole. Pp. 572-591. 262 F. Supp. 716, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"United States v. Perkins","cite":"116 U.S. 483","y":1886,"id":"scdb/1885-120","sc":1,"op":4,"sum":"When Congress by law, vests the appointment of inferior officers in the heads of departments, it may limit and restrict the power of removal as it deems best for the public interests.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"5","1":"24, 25, 40","3":"13"}},{"t":"case","label":"Wiener v. United States","cite":"357 U.S. 349","y":1958,"id":"1957/52","sc":1,"op":6,"ar":1,"sum":"The Court held that the President did not have the authority to remove individuals from the War Claims Commission at will.","sumSrc":"Oyez","by":{"0":"5, 19, 34","1":"22","2":"17","3":"10, 13"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"op":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"0":"22","2":"30"}},{"t":"case","label":"Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"0":"25"}},{"t":"const","label":"Article I, Section 2","clauses":[["apportionment","Apportionment and the Three-Fifths Clause"]],"by":{"0":"25"}},{"t":"const","label":"Article I, Section 3","by":{"0":"25"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"passim","1":"7, 10, 12, 15, 38","3":"2, 7, 12"}},{"t":"const","label":"Article II, Section 1","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"]],"by":{"0":"25"}},{"t":"const","label":"Article II, Section 1, Clause 1","clauses":[["executive-vesting","Executive Vesting Clause"]],"text":"The executive Power shall be vested in a President of the United States of America. He shall hold his Office during the Term of four Years, and, together with the Vice President, chosen for the same Term, be elected, as follows","by":{"0":"4, 15","3":"8"}},{"t":"const","label":"Article II, Section 2, Clause 2","clauses":[["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments.","by":{"0":"18","3":"9, 12"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"0":"4, 16","2":"18","3":"8"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"38","3":"4, 5, 20"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"0":"25"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"0":"passim","1":"2, 47","2":"passim","3":"3, 19, 21"}},{"t":"usc","label":"12 U.S.C. § 5302","url":"https://www.law.cornell.edu/uscode/text/12/5302","stext":{"head":"§5302. Severability","paras":[[0,"If any provision of this Act, an amendment made by this Act, or the application of such provision or amendment to any person or circumstance is held to be unconstitutional, the remainder of this Act, the amendments made by this Act, and the application of the provisions of such to any person or circumstance shall not be affected thereby."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5302?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§5302. Severability","tname":"Banks and Banking","by":{"0":"45","1":"4, 5, 47","2":"2, 10","3":"20"}},{"t":"usc","label":"12 U.S.C. § 5481","url":"https://www.law.cornell.edu/uscode/text/12/5481","subs":["(6)","(12)","(14)","(15)","(26)","(6)(A)"],"stext":{"head":"§5481. Definitions","paras":[[0,"Except as otherwise provided in this title,1 for purposes of this title,1 the following definitions shall apply:"],[0,"(1) Affiliate"],[1,"The term \"affiliate\" means any person that controls, is controlled by, or is under common control with another person."],[0,"(2) Bureau"],[1,"The term \"Bureau\" means the Bureau of Consumer Financial Protection."],[0,"(3) Business of insurance"],[1,"The term \"business of insurance\" means the writing of insurance or the reinsuring of risks by an insurer, including all acts necessary to such writing or reinsuring and the activities relating to the writing of insurance or the reinsuring of risks conducted by persons who act as, or are, officers, directors, agents, or employees of insurers or who are other persons authorized to act on behalf of such persons."],[0,"(4) Consumer"],[1,"The term \"consumer\" means an individual or an agent, trustee, or representative acting on behalf of an individual."],[0,"(5) Consumer financial product or service"],[1,"The term \"consumer financial product or service\" means any financial product or service that is described in one or more categories under—"],[2,"(A) paragraph (15) and is offered or provided for use by consumers primarily for personal, family, or household purposes; or"],[2,"(B) clause (i), (iii), (ix), or (x) of paragraph (15)(A), and is delivered, offered, or provided in connection with a consumer financial product or service referred to in subparagraph (A)."],[0,"(6) Covered person"],[1,"The term \"covered person\" means—"],[2,"(A) any person that engages in offering or providing a consumer financial product or service; and"],[2,"(B) any affiliate of a person described in subparagraph (A) if such affiliate acts as a service provider to such person."],[0,"(7) Credit"],[1,"The term \"credit\" means the right granted by a person to a consumer to defer payment of a debt, incur debt and defer its payment, or purchase property or services and defer payment for such purchase."],[0,"(8) Deposit-taking activity"],[1,"The term \"deposit-taking activity\" means—"],[2,"(A) the acceptance of deposits, maintenance of deposit accounts, or the provision of services related to the acceptance of deposits or the maintenance of deposit accounts;"],[2,"(B) the acceptance of funds, the provision of other services related to the acceptance of funds, or the maintenance of member share accounts by a credit union; or"],[2,"(C) the receipt of funds or the equivalent thereof, as the Bureau may determine by rule or order, received or held by a covered person (or an agent for a covered person) for the purpose of facilitating a payment or transferring funds or value of funds between a consumer and a third party."],[0,"(9) Designated transfer date"],[1,"The term \"designated transfer date\" means the date established under section 5582 of this title."],[0,"(10) Director"],[1,"The term \"Director\" means the Director of the Bureau."],[0,"(11) Electronic conduit services"],[1,"The term \"electronic conduit services\"—"],[2,"(A) means the provision, by a person, of electronic data transmission, routing, intermediate or transient storage, or connections to a telecommunications system or network; and"],[2,"(B) does not include a person that provides electronic conduit services if, when providing such services, the person—"],[3,"(i) selects or modifies the content of the electronic data;"],[3,"(ii) transmits, routes, stores, or provides connections for electronic data, including financial data, in a manner that such financial data is differentiated from other types of data of the same form that such person transmits, routes, or stores, or with respect to which, provides connections; or"],[3,"(iii) is a payee, payor, correspondent, or similar party to a payment transaction with a consumer."],[0,"(12) Enumerated consumer laws"],[1,"Except as otherwise specifically provided in section 5519 of this title, subtitle G or subtitle H, the term \"enumerated consumer laws\" means—"],[2,"(A) the Alternative Mortgage Transaction Parity Act of 1982 (12 U.S.C. 3801 et seq.);"],[2,"(B) the Consumer Leasing Act of 1976 (15 U.S.C. 1667 et seq.);"],[2,"(C) the Electronic Fund Transfer Act (15 U.S.C. 1693 et seq.), except with respect to section 920 of that Act [15 U.S.C. 1693o–2];"],[2,"(D) the Equal Credit Opportunity Act (15 U.S.C. 1691 et seq.);"],[2,"(E) the Fair Credit Billing Act (15 U.S.C. 1666 et seq.);"],[2,"(F) the Fair Credit Reporting Act (15 U.S.C. 1681 et seq.), except with respect to sections 615(e) and 628 of that Act (15 U.S.C. 1681m(e), 1681w);"],[2,"(G) the Home Owners 2 Protection Act of 1998 (12 U.S.C. 4901 et seq.);"],[2,"(H) the Fair Debt Collection Practices Act (15 U.S.C. 1692 et seq.);"],[2,"(I) subsections (b) through (f) of section 43 of the Federal Deposit Insurance Act (12 U.S.C. 1831t(c)[(b)]–(f));"],[2,"(J) sections 502 through 509 of the Gramm-Leach-Bliley Act (15 U.S.C. 6802–6809) except for section 505 [15 U.S.C. 6805] as it applies to section 501(b) [15 U.S.C. 6801(b)];"],[2,"(K) the Home Mortgage Disclosure Act of 1975 (12 U.S.C. 2801 et seq.);"],[2,"(L) the Home Ownership and Equity Protection Act of 1994 (15 U.S.C. 1601 note);"],[2,"(M) the Real Estate Settlement Procedures Act of 1974 (12 U.S.C. 2601 et seq.);"],[2,"(N) the S.A.F.E. Mortgage Licensing Act of 2008 (12 U.S.C. 5101 et seq.);"],[2,"(O) the Truth in Lending Act (15 U.S.C. 1601 et seq.);"],[2,"(P) the Truth in Savings Act (12 U.S.C. 4301 et seq.);"],[2,"(Q) section 626 of the Omnibus Appropriations Act, 2009 (Public Law 111–8) [12 U.S.C. 5538]; and"],[2,"(R) the Interstate Land Sales Full Disclosure Act (15 U.S.C. 1701)."],[0,"(13) Fair lending"],[1,"The term \"fair lending\" means fair, equitable, and nondiscriminatory access to credit for consumers."],[0,"(14) Federal consumer financial law"],[1,"The term \"Federal consumer financial law\" means the provisions of this title,1 the enumerated consumer laws, the laws for which authorities are transferred under subtitles F and H, and any rule or order prescribed by the Bureau under this title,1 an enumerated consumer law, or pursuant to the authorities transferred under subtitles F and H. The term does not include the Federal Trade Commission Act [15 U.S.C. 41 et seq.]."],[0,"(15) Financial product or service"],[0,"(A) In general"],[2,"The term \"financial product or service\" means—"],[3,"(i) extending credit and servicing loans, including acquiring, purchasing, selling, brokering, or other extensions of credit (other than solely extending commercial credit to a person who originates consumer credit transactions);"],[3,"(ii) extending or brokering leases of personal or real property that are the functional equivalent of purchase finance arrangements, if—"],[4,"(I) the lease is on a non-operating basis;"],[4,"(II) the initial term of the lease is at least 90 days; and"],[4,"(III) in the case of a lease involving real property, at the inception of the initial lease, the transaction is intended to result in ownership of the leased property to be transferred to the lessee, subject to standards prescribed by the Bureau;"],[3,"(iii) providing real estate settlement services, except such services excluded under subparagraph (C), or performing appraisals of real estate or personal property;"],[3,"(iv) engaging in deposit-taking activities, transmitting or exchanging funds, or otherwise acting as a custodian of funds or any financial instrument for use by or on behalf of a consumer;"],[3,"(v) selling, providing, or issuing stored value or payment instruments, except that, in the case of a sale of, or transaction to reload, stored value, only if the seller exercises substantial control over the terms or conditions of the stored value provided to the consumer where, for purposes of this clause—"],[4,"(I) a seller shall not be found to exercise substantial control over the terms or conditions of the stored value if the seller is not a party to the contract with the consumer for the stored value product, and another person is principally responsible for establishing the terms or conditions of the stored value; and"],[4,"(II) advertising the nonfinancial goods or services of the seller on the stored value card or device is not in itself an exercise of substantial control over the terms or conditions;"],[3,"(vi) providing check cashing, check collection, or check guaranty services;"],[3,"(vii) providing payments or other financial data processing products or services to a consumer by any technological means, including processing or storing financial or banking data for any payment instrument, or through any payments systems or network used for processing payments data, including payments made through an online banking system or mobile telecommunications network, except that a person shall not be deemed to be a covered person with respect to financial data processing solely because the person—"],[4,"(I) is a merchant, retailer, or seller of any nonfinancial good or service who engages in financial data processing by transmitting or storing payments data about a consumer exclusively for purpose of initiating payments instructions by the consumer to pay such person for the purchase of, or to complete a commercial transaction for, such nonfinancial good or service sold directly by such person to the consumer; or"],[4,"(II) provides access to a host server to a person for purposes of enabling that person to establish and maintain a website;"],[3,"(viii) providing financial advisory services (other than services relating to securities provided by a person regulated by the Commission or a person regulated by a State securities Commission, but only to the extent that such person acts in a regulated capacity) to consumers on individual financial matters or relating to proprietary financial products or services (other than by publishing any bona fide newspaper, news magazine, or business or financial publication of general and regular circulation, including publishing market data, news, or data analytics or investment information or recommendations that are not tailored to the individual needs of a particular consumer), including—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5481?type=usc&year=mostrecent&link-type=html"},"head":"§5481. Definitions","tname":"Banks and Banking","by":{"0":"7, 27, 7, 27, 46, 7, 27, 46, 7, 27","1":"3, 48, 48"}},{"t":"usc","label":"12 U.S.C. § 5491","url":"https://www.law.cornell.edu/uscode/text/12/5491","subs":["(a)","(b)(1)","(b)(2)","(c)(1)","(c)(2)","(c)(3)"],"stext":{"head":"§5491. Establishment of the Bureau of Consumer Financial Protection","paras":[[0,"(a) Bureau established"],[0,"There is established in the Federal Reserve System, an independent bureau to be known as the \"Bureau of Consumer Financial Protection\", which shall regulate the offering and provision of consumer financial products or services under the Federal consumer financial laws. The Bureau shall be considered an Executive agency, as defined in section 105 of title 5. Except as otherwise provided expressly by law, all Federal laws dealing with public or Federal contracts, property, works, officers, employees, budgets, or funds, including the provisions of chapters 5 and 7 of title 5, shall apply to the exercise of the powers of the Bureau."],[0,"(b) Director and Deputy Director"],[0,"(1) In general"],[1,"There is established the position of the Director, who shall serve as the head of the Bureau."],[0,"(2) Appointment"],[1,"Subject to paragraph (3), the Director shall be appointed by the President, by and with the advice and consent of the Senate."],[0,"(3) Qualification"],[1,"The President shall nominate the Director from among individuals who are citizens of the United States."],[0,"(4) Compensation"],[1,"The Director shall be compensated at the rate prescribed for level II of the Executive Schedule under section 5313 of title 5."],[0,"(5) Deputy Director"],[1,"There is established the position of Deputy Director, who shall—"],[2,"(A) be appointed by the Director; and"],[2,"(B) serve as acting Director in the absence or unavailability of the Director."],[0,"(c) Term"],[0,"(1) In general"],[1,"The Director shall serve for a term of 5 years."],[0,"(2) Expiration of term"],[1,"An individual may serve as Director after the expiration of the term for which appointed, until a successor has been appointed and qualified."],[0,"(3) Removal for cause"],[1,"The President may remove the Director for inefficiency, neglect of duty, or malfeasance in office."],[0,"(d) Service restriction"],[0,"No Director or Deputy Director may hold any office, position, or employment in any Federal reserve bank, Federal home loan bank, covered person, or service provider during the period of service of such person as Director or Deputy Director."],[0,"(e) Offices"],[0,"The principal office of the Bureau shall be in the District of Columbia. The Director may establish regional offices of the Bureau, including in cities in which the Federal reserve banks, or branches of such banks, are located, in order to carry out the responsibilities assigned to the Bureau under the Federal consumer financial laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5491?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§5491. Establishment of the Bureau of Consumer Financial Protection","tname":"Banks and Banking","by":{"0":"6, 42, 6, 18, 6, 6, 6, passim","1":"48, 48, 48, 48, 48","2":"passim","3":"17"}},{"t":"usc","label":"12 U.S.C. § 5492","url":"https://www.law.cornell.edu/uscode/text/12/5492","subs":["(c)(3)"],"by":{"0":"43"}},{"t":"usc","label":"12 U.S.C. § 5497","url":"https://www.law.cornell.edu/uscode/text/12/5497","subs":["(a)","(a)(1)","(a)(2)(A)(iii)","(a)(2)(B)","(a)(4)(E)","(e)"],"by":{"0":"43, 7, 7, 7, 43, 7","1":"48, 48"}},{"t":"usc","label":"12 U.S.C. § 5511","url":"https://www.law.cornell.edu/uscode/text/12/5511","subs":["(a)"],"stext":{"head":"§5511. Purpose, objectives, and functions","paras":[[0,"(a) Purpose"],[0,"The Bureau shall seek to implement and, where applicable, enforce Federal consumer financial law consistently for the purpose of ensuring that all consumers have access to markets for consumer financial products and services and that markets for consumer financial products and services are fair, transparent, and competitive."],[0,"(b) Objectives"],[0,"The Bureau is authorized to exercise its authorities under Federal consumer financial law for the purposes of ensuring that, with respect to consumer financial products and services—"],[1,"(1) consumers are provided with timely and understandable information to make responsible decisions about financial transactions;"],[1,"(2) consumers are protected from unfair, deceptive, or abusive acts and practices and from discrimination;"],[1,"(3) outdated, unnecessary, or unduly burdensome regulations are regularly identified and addressed in order to reduce unwarranted regulatory burdens;"],[1,"(4) Federal consumer financial law is enforced consistently, without regard to the status of a person as a depository institution, in order to promote fair competition; and"],[1,"(5) markets for consumer financial products and services operate transparently and efficiently to facilitate access and innovation."],[0,"(c) Functions"],[0,"The primary functions of the Bureau are—"],[1,"(1) conducting financial education programs;"],[1,"(2) collecting, investigating, and responding to consumer complaints;"],[1,"(3) collecting, researching, monitoring, and publishing information relevant to the functioning of markets for consumer financial products and services to identify risks to consumers and the proper functioning of such markets;"],[1,"(4) subject to sections 5514 through 5516 of this title, supervising covered persons for compliance with Federal consumer financial law, and taking appropriate enforcement action to address violations of Federal consumer financial law;"],[1,"(5) issuing rules, orders, and guidance implementing Federal consumer financial law; and"],[1,"(6) performing such support activities as may be necessary or useful to facilitate the other functions of the Bureau."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5511?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5511. Purpose, objectives, and functions","tname":"Banks and Banking","by":{"0":"6","1":"2, 48","2":"19"}},{"t":"usc","label":"12 U.S.C. § 5531","url":"https://www.law.cornell.edu/uscode/text/12/5531","subs":["(a)","(b)"],"stext":{"head":"§5531. Prohibiting unfair, deceptive, or abusive acts or practices","paras":[[0,"(a) In general"],[0,"The Bureau may take any action authorized under part E to prevent a covered person or service provider from committing or engaging in an unfair, deceptive, or abusive act or practice under Federal law in connection with any transaction with a consumer for a consumer financial product or service, or the offering of a consumer financial product or service."],[0,"(b) Rulemaking"],[0,"The Bureau may prescribe rules applicable to a covered person or service provider identifying as unlawful unfair, deceptive, or abusive acts or practices in connection with any transaction with a consumer for a consumer financial product or service, or the offering of a consumer financial product or service. Rules under this section may include requirements for the purpose of preventing such acts or practices."],[0,"(c) Unfairness"],[0,"(1) In general"],[1,"The Bureau shall have no authority under this section to declare an act or practice in connection with a transaction with a consumer for a consumer financial product or service, or the offering of a consumer financial product or service, to be unlawful on the grounds that such act or practice is unfair, unless the Bureau has a reasonable basis to conclude that—"],[2,"(A) the act or practice causes or is likely to cause substantial injury to consumers which is not reasonably avoidable by consumers; and"],[2,"(B) such substantial injury is not outweighed by countervailing benefits to consumers or to competition."],[0,"(2) Consideration of public policies"],[1,"In determining whether an act or practice is unfair, the Bureau may consider established public policies as evidence to be considered with all other evidence. Such public policy considerations may not serve as a primary basis for such determination."],[0,"(d) Abusive"],[0,"The Bureau shall have no authority under this section to declare an act or practice abusive in connection with the provision of a consumer financial product or service, unless the act or practice—"],[1,"(1) materially interferes with the ability of a consumer to understand a term or condition of a consumer financial product or service; or"],[1,"(2) takes unreasonable advantage of—"],[2,"(A) a lack of understanding on the part of the consumer of the material risks, costs, or conditions of the product or service;"],[2,"(B) the inability of the consumer to protect the interests of the consumer in selecting or using a consumer financial product or service; or"],[2,"(C) the reasonable reliance by the consumer on a covered person to act in the interests of the consumer."],[0,"(e) Consultation"],[0,"In prescribing rules under this section, the Bureau shall consult with the Federal banking agencies, or other Federal agencies, as appropriate, concerning the consistency of the proposed rule with prudential, market, or systemic objectives administered by such agencies."],[0,"(f) Consideration of seasonal income"],[0,"The rules of the Bureau under this section shall provide, with respect to an extension of credit secured by residential real estate or a dwelling, if documented income of the borrower, including income from a small business, is a repayment source for an extension of credit secured by residential real estate or a dwelling, the creditor may consider the seasonality and irregularity of such income in the underwriting of and scheduling of payments for such credit."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5531?type=usc&year=mostrecent&link-type=html"},"head":"§5531. Prohibiting unfair, deceptive, or abusive acts or practices","tname":"Banks and Banking","by":{"0":"7, 27, 37, 7, 27","1":"3","2":"19"}},{"t":"usc","label":"12 U.S.C. § 5536","url":"https://www.law.cornell.edu/uscode/text/12/5536","subs":["(a)(1)(B)"],"by":{"0":"7, 27, 46","1":"3"}},{"t":"usc","label":"12 U.S.C. § 5562","url":"https://www.law.cornell.edu/uscode/text/12/5562","subs":["(e)(1)","(f)","(c)(1)","(c)(1)(A)"],"stext":{"head":"§5562. Investigations and administrative discovery","paras":[[0,"(a) Joint investigations"],[0,"(1) In general"],[1,"The Bureau or, where appropriate, a Bureau investigator, may engage in joint investigations and requests for information, as authorized under this title.1"],[0,"(2) Fair lending"],[1,"The authority under paragraph (1) includes matters relating to fair lending, and where appropriate, joint investigations with, and requests for information from, the Secretary of Housing and Urban Development, the Attorney General of the United States, or both."],[0,"(b) Subpoenas"],[0,"(1) In general"],[1,"The Bureau or a Bureau investigator may issue subpoenas for the attendance and testimony of witnesses and the production of relevant papers, books, documents, or other material in connection with hearings under this title.1"],[0,"(2) Failure to obey"],[1,"In the case of contumacy or refusal to obey a subpoena issued pursuant to this paragraph and served upon any person, the district court of the United States for any district in which such person is found, resides, or transacts business, upon application by the Bureau or a Bureau investigator and after notice to such person, may issue an order requiring such person to appear and give testimony or to appear and produce documents or other material."],[0,"(3) Contempt"],[1,"Any failure to obey an order of the court under this subsection may be punished by the court as a contempt thereof."],[0,"(c) Demands"],[0,"(1) In general"],[1,"Whenever the Bureau has reason to believe that any person may be in possession, custody, or control of any documentary material or tangible things, or may have any information, relevant to a violation, the Bureau may, before the institution of any proceedings under the Federal consumer financial law, issue in writing, and cause to be served upon such person, a civil investigative demand requiring such person to—"],[2,"(A) produce such documentary material for inspection and copying or reproduction in the form or medium requested by the Bureau;"],[2,"(B) submit such tangible things;"],[2,"(C) file written reports or answers to questions;"],[2,"(D) give oral testimony concerning documentary material, tangible things, or other information; or"],[2,"(E) furnish any combination of such material, answers, or testimony."],[0,"(2) Requirements"],[1,"Each civil investigative demand shall state the nature of the conduct constituting the alleged violation which is under investigation and the provision of law applicable to such violation."],[0,"(3) Production of documents"],[1,"Each civil investigative demand for the production of documentary material shall—"],[2,"(A) describe each class of documentary material to be produced under the demand with such definiteness and certainty as to permit such material to be fairly identified;"],[2,"(B) prescribe a return date or dates which will provide a reasonable period of time within which the material so demanded may be assembled and made available for inspection and copying or reproduction; and"],[2,"(C) identify the custodian to whom such material shall be made available."],[0,"(4) Production of things"],[1,"Each civil investigative demand for the submission of tangible things shall—"],[2,"(A) describe each class of tangible things to be submitted under the demand with such definiteness and certainty as to permit such things to be fairly identified;"],[2,"(B) prescribe a return date or dates which will provide a reasonable period of time within which the things so demanded may be assembled and submitted; and"],[2,"(C) identify the custodian to whom such things shall be submitted."],[0,"(5) Demand for written reports or answers"],[1,"Each civil investigative demand for written reports or answers to questions shall—"],[2,"(A) propound with definiteness and certainty the reports to be produced or the questions to be answered;"],[2,"(B) prescribe a date or dates at which time written reports or answers to questions shall be submitted; and"],[2,"(C) identify the custodian to whom such reports or answers shall be submitted."],[0,"(6) Oral testimony"],[1,"Each civil investigative demand for the giving of oral testimony shall—"],[2,"(A) prescribe a date, time, and place at which oral testimony shall be commenced; and"],[2,"(B) identify a Bureau investigator who shall conduct the investigation and the custodian to whom the transcript of such investigation shall be submitted."],[0,"(7) Service"],[1,"Any civil investigative demand issued, and any enforcement petition filed, under this section may be served—"],[2,"(A) by any Bureau investigator at any place within the territorial jurisdiction of any court of the United States; and"],[2,"(B) upon any person who is not found within the territorial jurisdiction of any court of the United States—"],[3,"(i) in such manner as the Federal Rules of Civil Procedure prescribe for service in a foreign nation; and"],[3,"(ii) to the extent that the courts of the United States have authority to assert jurisdiction over such person, consistent with due process, the United States District Court for the District of Columbia shall have the same jurisdiction to take any action respecting compliance with this section by such person that such district court would have if such person were personally within the jurisdiction of such district court."],[0,"(8) Method of service"],[1,"Service of any civil investigative demand or any enforcement petition filed under this section may be made upon a person, including any legal entity, by—"],[2,"(A) delivering a duly executed copy of such demand or petition to the individual or to any partner, executive officer, managing agent, or general agent of such person, or to any agent of such person authorized by appointment or by law to receive service of process on behalf of such person;"],[2,"(B) delivering a duly executed copy of such demand or petition to the principal office or place of business of the person to be served; or"],[2,"(C) depositing a duly executed copy in the United States mails, by registered or certified mail, return receipt requested, duly addressed to such person at the principal office or place of business of such person."],[0,"(9) Proof of service"],[0,"(A) In general"],[2,"A verified return by the individual serving any civil investigative demand or any enforcement petition filed under this section setting forth the manner of such service shall be proof of such service."],[0,"(B) Return receipts"],[2,"In the case of service by registered or certified mail, such return shall be accompanied by the return post office receipt of delivery of such demand or enforcement petition."],[0,"(10) Production of documentary material"],[1,"The production of documentary material in response to a civil investigative demand shall be made under a sworn certificate, in such form as the demand designates, by the person, if a natural person, to whom the demand is directed or, if not a natural person, by any person having knowledge of the facts and circumstances relating to such production, to the effect that all of the documentary material required by the demand and in the possession, custody, or control of the person to whom the demand is directed has been produced and made available to the custodian."],[0,"(11) Submission of tangible things"],[1,"The submission of tangible things in response to a civil investigative demand shall be made under a sworn certificate, in such form as the demand designates, by the person to whom the demand is directed or, if not a natural person, by any person having knowledge of the facts and circumstances relating to such production, to the effect that all of the tangible things required by the demand and in the possession, custody, or control of the person to whom the demand is directed have been submitted to the custodian."],[0,"(12) Separate answers"],[1,"Each reporting requirement or question in a civil investigative demand shall be answered separately and fully in writing under oath, unless it is objected to, in which event the reasons for the objection shall be stated in lieu of an answer, and it shall be submitted under a sworn certificate, in such form as the demand designates, by the person, if a natural person, to whom the demand is directed or, if not a natural person, by any person responsible for answering each reporting requirement or question, to the effect that all information required by the demand and in the possession, custody, control, or knowledge of the person to whom the demand is directed has been submitted."],[0,"(13) Testimony"],[0,"(A) In general"],[0,"(i) Oath and recordation"],[3,"The examination of any person pursuant to a demand for oral testimony served under this subsection shall be taken before an officer authorized to administer oaths and affirmations by the laws of the United States or of the place at which the examination is held. The officer before whom oral testimony is to be taken shall put the witness on oath or affirmation and shall personally, or by any individual acting under the direction of and in the presence of the officer, record the testimony of the witness."],[0,"(ii) Transcription"],[3,"The testimony shall be taken stenographically and transcribed."],[0,"(iii) Transmission to custodian"],[3,"After the testimony is fully transcribed, the officer investigator before whom the testimony is taken shall promptly transmit a copy of the transcript of the testimony to the custodian."],[0,"(B) Parties present"],[2,"Any Bureau investigator before whom oral testimony is to be taken shall exclude from the place where the testimony is to be taken all other persons, except the person giving the testimony, the attorney for that person, the officer before whom the testimony is to be taken, an investigator or representative of an agency with which the Bureau is engaged in a joint investigation, and any stenographer taking such testimony."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5562?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5562. Investigations and administrative discovery","tname":"Banks and Banking","by":{"0":"7, 18, 8, 35, 8","1":"18, 18, 18, 18, 18","2":"20, 6"}},{"t":"usc","label":"12 U.S.C. § 5564","url":"https://www.law.cornell.edu/uscode/text/12/5564","subs":["(a)","(f)"],"stext":{"head":"§5564. Litigation authority","paras":[[0,"(a) In general"],[0,"If any person violates a Federal consumer financial law, the Bureau may, subject to sections 5514, 5515, and 5516 of this title, commence a civil action against such person to impose a civil penalty or to seek all appropriate legal and equitable relief including a permanent or temporary injunction as permitted by law."],[0,"(b) Representation"],[0,"The Bureau may act in its own name and through its own attorneys in enforcing any provision of this title,1 rules thereunder, or any other law or regulation, or in any action, suit, or proceeding to which the Bureau is a party."],[0,"(c) Compromise of actions"],[0,"The Bureau may compromise or settle any action if such compromise is approved by the court."],[0,"(d) Notice to the Attorney General"],[0,"(1) In general"],[1,"When commencing a civil action under Federal consumer financial law, or any rule thereunder, the Bureau shall notify the Attorney General and, with respect to a civil action against an insured depository institution or insured credit union, the appropriate prudential regulator."],[0,"(2) Notice and coordination"],[0,"(A) Notice of other actions"],[2,"In addition to any notice required under paragraph (1), the Bureau shall notify the Attorney General concerning any action, suit, or proceeding to which the Bureau is a party, except an action, suit, or proceeding that involves the offering or provision of consumer financial products or services."],[0,"(B) Coordination"],[2,"In order to avoid conflicts and promote consistency regarding litigation of matters under Federal law, the Attorney General and the Bureau shall consult regarding the coordination of investigations and proceedings, including by negotiating an agreement for coordination by not later than 180 days after the designated transfer date. The agreement under this subparagraph shall include provisions to ensure that parallel investigations and proceedings involving the Federal consumer financial laws are conducted in a manner that avoids conflicts and does not impede the ability of the Attorney General to prosecute violations of Federal criminal laws."],[0,"(C) Rule of construction"],[2,"Nothing in this paragraph shall be construed to limit the authority of the Bureau under this title,1 including the authority to interpret Federal consumer financial law."],[0,"(e) Appearance before the Supreme Court"],[0,"The Bureau may represent itself in its own name before the Supreme Court of the United States, provided that the Bureau makes a written request to the Attorney General within the 10-day period which begins on the date of entry of the judgment which would permit any party to file a petition for writ of certiorari, and the Attorney General concurs with such request or fails to take action within 60 days of the request of the Bureau."],[0,"(f) Forum"],[0,"Any civil action brought under this title 1 may be brought in a United States district court or in any court of competent jurisdiction of a state in a district in which the defendant is located or resides or is doing business, and such court shall have jurisdiction to enjoin such person and to require compliance with any Federal consumer financial law."],[0,"(g) Time for bringing action"],[0,"(1) In general"],[1,"Except as otherwise permitted by law or equity, no action may be brought under this title 1 more than 3 years after the date of discovery of the violation to which an action relates."],[0,"(2) Limitations under other Federal laws"],[0,"(A) In general"],[2,"An action arising under this title 1 does not include claims arising solely under enumerated consumer laws."],[0,"(B) Bureau authority"],[2,"In any action arising solely under an enumerated consumer law, the Bureau may commence, defend, or intervene in the action in accordance with the requirements of that provision of law, as applicable."],[0,"(C) Transferred authority"],[2,"In any action arising solely under laws for which authorities were transferred under subtitles F and H, the Bureau may commence, defend, or intervene in the action in accordance with the requirements of that provision of law, as applicable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5564?type=usc&year=mostrecent&link-type=html"},"head":"§5564. Litigation authority","tname":"Banks and Banking","by":{"0":"7, 18, 7, 18","1":"18","2":"20"}},{"t":"usc","label":"12 U.S.C. § 5581","url":"https://www.law.cornell.edu/uscode/text/12/5581","subs":["(a)(1)(A)","(a)(2)(A)"],"stext":{"head":"§5581. Transfer of consumer financial protection functions","paras":[[0,"(a) Defined terms"],[0,"For purposes of this part—"],[1,"(1) the term \"consumer financial protection functions\" means—"],[2,"(A) all authority to prescribe rules or issue orders or guidelines pursuant to any Federal consumer financial law, including performing appropriate functions to promulgate and review such rules, orders, and guidelines; and"],[2,"(B) the examination authority described in subsection (c)(1), with respect to a person described in section 5515(a) of this title; and"],[1,"(2) the terms \"transferor agency\" and \"transferor agencies\" mean, respectively—"],[2,"(A) the Board of Governors (and any Federal reserve bank, as the context requires), the Federal Deposit Insurance Corporation, the Federal Trade Commission, the National Credit Union Administration, the Office of the Comptroller of the Currency, the Office of Thrift Supervision, and the Department of Housing and Urban Development, and the heads of those agencies; and"],[2,"(B) the agencies listed in subparagraph (A), collectively."],[0,"(b) In general"],[0,"Except as provided in subsection (c), consumer financial protection functions are transferred as follows:"],[0,"(1) Board of Governors"],[0,"(A) Transfer of functions"],[2,"All consumer financial protection functions of the Board of Governors are transferred to the Bureau."],[0,"(B) Board of Governors authority"],[2,"The Bureau shall have all powers and duties that were vested in the Board of Governors, relating to consumer financial protection functions, on the day before the designated transfer date."],[0,"(2) Comptroller of the Currency"],[0,"(A) Transfer of functions"],[2,"All consumer financial protection functions of the Comptroller of the Currency are transferred to the Bureau."],[0,"(B) Comptroller authority"],[2,"The Bureau shall have all powers and duties that were vested in the Comptroller of the Currency, relating to consumer financial protection functions, on the day before the designated transfer date."],[0,"(3) Director of the Office of Thrift Supervision"],[0,"(A) Transfer of functions"],[2,"All consumer financial protection functions of the Director of the Office of Thrift Supervision are transferred to the Bureau."],[0,"(B) Director authority"],[2,"The Bureau shall have all powers and duties that were vested in the Director of the Office of Thrift Supervision, relating to consumer financial protection functions, on the day before the designated transfer date."],[0,"(4) Federal Deposit Insurance Corporation"],[0,"(A) Transfer of functions"],[2,"All consumer financial protection functions of the Federal Deposit Insurance Corporation are transferred to the Bureau."],[0,"(B) Corporation authority"],[2,"The Bureau shall have all powers and duties that were vested in the Federal Deposit Insurance Corporation, relating to consumer financial protection functions, on the day before the designated transfer date."],[0,"(5) Federal Trade Commission"],[0,"(A) Transfer of functions"],[2,"The authority of the Federal Trade Commission under an enumerated consumer law to prescribe rules, issue guidelines, or conduct a study or issue a report mandated under such law shall be transferred to the Bureau on the designated transfer date. Nothing in this title 1 shall be construed to require a mandatory transfer of any employee of the Federal Trade Commission."],[0,"(B) Bureau authority"],[0,"(i) In general"],[3,"The Bureau shall have all powers and duties under the enumerated consumer laws to prescribe rules, issue guidelines, or to conduct studies or issue reports mandated by such laws, that were vested in the Federal Trade Commission on the day before the designated transfer date."],[0,"(ii) Federal Trade Commission Act"],[3,"Subject to part B, the Bureau may enforce a rule prescribed under the Federal Trade Commission Act [15 U.S.C. 41 et seq.] by the Federal Trade Commission with respect to an unfair or deceptive act or practice to the extent that such rule applies to a covered person or service provider with respect to the offering or provision of a consumer financial product or service as if it were a rule prescribed under section 5531 of this title."],[0,"(C) Authority of the Federal Trade Commission"],[0,"(i) In general"],[3,"No provision of this title 1 shall be construed as modifying, limiting, or otherwise affecting the authority of the Federal Trade Commission (including its authority with respect to affiliates described in section 5515(a)(1) of this title) under the Federal Trade Commission Act or any other law, other than the authority under an enumerated consumer law to prescribe rules, issue official guidelines, or conduct a study or issue a report mandated under such law."],[0,"(ii) Commission authority relating to rules prescribed by the Bureau"],[3,"Subject to part B, the Federal Trade Commission shall have authority to enforce under the Federal Trade Commission Act (15 U.S.C. 41 et seq.) a rule prescribed by the Bureau under this title 1 with respect to a covered person subject to the jurisdiction of the Federal Trade Commission under that Act, and a violation of such a rule by such a person shall be treated as a violation of a rule issued under section 18 of that Act (15 U.S.C. 57a) with respect to unfair or deceptive acts or practices."],[0,"(D) Coordination"],[2,"To avoid duplication of or conflict between rules prescribed by the Bureau under section 5531 of this title and the Federal Trade Commission under section 18(a)(1)(B) of the Federal Trade Commission Act [15 U.S.C. 57a(a)(1)(B)] that apply to a covered person or service provider with respect to the offering or provision of consumer financial products or services, the agencies shall negotiate an agreement with respect to rulemaking by each agency, including consultation with the other agency prior to proposing a rule and during the comment period."],[0,"(E) Deference"],[2,"No provision of this title 1 shall be construed as altering, limiting, expanding, or otherwise affecting the deference that a court affords to the—"],[3,"(i) Federal Trade Commission in making determinations regarding the meaning or interpretation of any provision of the Federal Trade Commission Act, or of any other Federal law for which the Commission has authority to prescribe rules; or"],[3,"(ii) Bureau in making determinations regarding the meaning or interpretation of any provision of a Federal consumer financial law (other than any law described in clause (i))."],[0,"(6) National Credit Union Administration"],[0,"(A) Transfer of functions"],[2,"All consumer financial protection functions of the National Credit Union Administration are transferred to the Bureau."],[0,"(B) National Credit Union Administration authority"],[2,"The Bureau shall have all powers and duties that were vested in the National Credit Union Administration, relating to consumer financial protection functions, on the day before the designated transfer date."],[0,"(7) Department of Housing and Urban Development"],[0,"(A) Transfer of functions"],[2,"All consumer protection functions of the Secretary of the Department of Housing and Urban Development relating to the Real Estate Settlement Procedures Act of 1974 (12 U.S.C. 2601 et seq.), the Secure and Fair Enforcement for Mortgage Licensing Act of 2008 (12 U.S.C. 5102 [5101] et seq.), and the Interstate Land Sales Full Disclosure Act (15 U.S.C. 1701 et seq.) are transferred to the Bureau."],[0,"(B) Authority of the Department of Housing and Urban Development"],[2,"The Bureau shall have all powers and duties that were vested in the Secretary of the Department of Housing and Urban Development relating to the Real Estate Settlement Procedures Act of 1974 (12 U.S.C. 2601 et seq.), the Secure and Fair Enforcement for Mortgage Licensing Act of 2008 (12 U.S.C. 5101 et seq.), and the Interstate Land Sales Full Disclosure Act (15 U.S.C. 1701 et seq.), on the day before the designated transfer date."],[0,"(c) Authorities of the prudential regulators"],[0,"(1) Examination"],[1,"A transferor agency that is a prudential regulator shall have—"],[2,"(A) authority to require reports from and conduct examinations for compliance with Federal consumer financial laws with respect to a person described in section 5515(a) of this title, that is incidental to the backup and enforcement procedures provided to the regulator under section 5515(c) of this title; and"],[2,"(B) exclusive authority (relative to the Bureau) to require reports from and conduct examinations for compliance with Federal consumer financial laws with respect to a person described in section 5516(a) of this title, except as provided to the Bureau under subsections (b) and (c) of section 5516 of this title."],[0,"(2) Enforcement"],[0,"(A) Limitation"],[2,"The authority of a transferor agency that is a prudential regulator to enforce compliance with Federal consumer financial laws with respect to a person described in section 5515(a) of this title, shall be limited to the backup and enforcement procedures in 2 described in section 5515(c) of this title."],[0,"(B) Exclusive authority"],[2,"A transferor agency that is a prudential regulator shall have exclusive authority (relative to the Bureau) to enforce compliance with Federal consumer financial laws with respect to a person described in section 5516(a) of this title, except as provided to the Bureau under subsections (b) and (c) of section 5516 of this title."],[0,"(C) Statutory enforcement"],[2,"For purposes of carrying out the authorities under, and subject to the limitations of, part B, each prudential regulator may enforce compliance with the requirements imposed under this title,1 and any rule or order prescribed by the Bureau under this title,1 under—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5581?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§5581. Transfer of consumer financial protection functions","tname":"Banks and Banking","by":{"0":"43, 6, 27, 46","1":"18"}},{"t":"usc","label":"15 U.S.C. § 8232","url":"https://www.law.cornell.edu/uscode/text/15/8232","stext":{"head":"§8232. Severability","paras":[[0,"If any section or subsection of this chapter, or any application of such provision to any person or circumstance, is held to be unconstitutional, the remainder of this chapter, and the application of the provision to any other person or circumstance, shall not be affected."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/8232?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§8232. Severability","tname":"Commerce and Trade","by":{"0":"45","3":"21"}},{"t":"law","label":"Housing and Economic Recovery Act, Pub. L. No. 110-289","url":"https://www.govinfo.gov/link/plaw/110/public/289","by":{"0":"24"}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","stext":{"head":"§41. Federal Trade Commission established; membership; vacancies; seal","paras":[[0,"A commission is created and established, to be known as the Federal Trade Commission (hereinafter referred to as the Commission), which shall be composed of five Commissioners, who shall be appointed by the President, by and with the advice and consent of the Senate. Not more than three of the Commissioners shall be members of the same political party. The first Commissioners appointed shall continue in office for terms of three, four, five, six, and seven years, respectively, from September 26, 1914, the term of each to be designated by the President, but their successors shall be appointed for terms of seven years, except that any person chosen to fill a vacancy shall be appointed only for the unexpired term of the Commissioner whom he shall succeed: Provided, however, That upon the expiration of his term of office a Commissioner shall continue to serve until his successor shall have been appointed and shall have qualified..1 The President shall choose a chairman from the Commission's membership. No Commissioner shall engage in any other business, vocation, or employment. Any Commissioner may be removed by the President for inefficiency, neglect of duty, or malfeasance in office. A vacancy in the Commission shall not impair the right of the remaining Commissioners to exercise all the powers of the Commission."],[0,"The Commission shall have an official seal, which shall be judicially noticed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/41?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§41. Federal Trade Commission established; membership; vacancies; seal","tname":"Commerce and Trade","by":{"0":"4, 19","2":"20"}},{"t":"usc","label":"28 U.S.C. § 596","url":"https://www.law.cornell.edu/uscode/text/28/596","subs":["(a)(1)"],"by":{"0":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"reg","label":"12 C.F.R. § 1080.6","url":"https://www.ecfr.gov/current/title-12/section-1080.6","subs":["(e)"],"by":{"0":"8"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"op":3,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Edmond v. United States","cite":"520 U.S. 651","y":1997,"id":"1996/96-262","sc":1,"op":1,"sum":"The Court held that the judicial appointments were valid. The Court unanimously found that Congress has authorized the Secretary to appoint civilian members of the Coast Guard Court of Criminal Appeals.","sumSrc":"Oyez","by":{"1":"11","2":"31"}},{"t":"case","label":"Franchise Tax Bd. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"45"}},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Janus v. American Fed’n of State, County, & Mun. Emps.","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"1":"44, 45, 46"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"1":"30","2":"26, 30"}},{"t":"case","label":"Morgan v. Daniels","cite":"153 U.S. 120","y":1894,"id":"scdb/1893-220","sc":1,"sum":"When a question between contending parties, as to priority of invention, is decided in the Patent Office, the decision there made must be accepted as controlling, upon that question of fact, in any subsequent suit between the same parties, unless the contrary is established by testimony which, in character and amount, carries thorough conviction.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"op":2,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"1":"33","2":"30"}},{"t":"case","label":"Panama Ref. Co. v. Ryan","cite":"293 U.S. 388","y":1935,"id":"1900-1940/293us388","sc":1,"sum":"Writing for the 8-1 majority, Chief Justice Charles E. Hughes concluded the order was not constitutional. Supreme Court held that in enacting the order, the President subsumed legislative powers that Congress does not have the power to delegate. Congress cannot delegate legislative powers to other branches of government in order to sustain the democratic system of government.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Parsons v. United States","cite":"167 U.S. 324","y":1897,"id":"scdb/1896-203","sc":1,"op":1,"sum":"The President has power to remove a district attorney of the United States, when such removal occurs within four years from the date of the attorney’s appointment, and, with the advice and consent of the Senate, to appoint a successor to him.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"op":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Tagg Bros. & Moorhead v. United States","cite":"280 U.S. 420","y":1930,"id":"scdb/1929-133","sc":1,"sum":"(1) The rates of such market agencies are subject to regulation, under authority of Congress, to prevent their services from becoming an undue burden upon, or obstruction of, interstate commerce. Pp. 436-9. (2) Such regulation is not an attempt to fix wages or limit anyone's net income, and does not violate the due process clause. P. 439. (3) The mere division of the stockyard services between 'the stockyards …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"law","label":"Pub. L. No. 95-454","url":"https://www.govinfo.gov/link/statute/92/1122","by":{"1":"33","2":"26"}},{"t":"usc","label":"5 U.S.C. § 1212","url":"https://www.law.cornell.edu/uscode/text/5/1212","stext":{"head":"§1212. Powers and functions of the Office of Special Counsel","paras":[[0,"(a) The Office of Special Counsel shall—"],[1,"(1) in accordance with section 1214(a) and other applicable provisions of this subchapter, protect employees, former employees, and applicants for employment from prohibited personnel practices;"],[1,"(2) receive and investigate allegations of prohibited personnel practices, and, where appropriate—"],[2,"(A) bring petitions for stays, and petitions for corrective action, under section 1214; and"],[2,"(B) file a complaint or make recommendations for disciplinary action under section 1215;"],[1,"(3) receive, review, and, where appropriate, forward to the Attorney General or an agency head under section 1213, disclosures of violations of any law, rule, or regulation, or gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety;"],[1,"(4) review rules and regulations issued by the Director of the Office of Personnel Management in carrying out functions under section 1103 and, where the Special Counsel finds that any such rule or regulation would, on its face or as implemented, require the commission of a prohibited personnel practice, file a written complaint with the Board; and"],[1,"(5) investigate and, where appropriate, bring actions concerning allegations of violations of other laws within the jurisdiction of the Office of Special Counsel (as referred to in section 1216)."],[0,"(b)(1) The Special Counsel and any employee of the Office of Special Counsel designated by the Special Counsel may administer oaths, examine witnesses, take depositions, and receive evidence."],[0,"(2) The Special Counsel may—"],[1,"(A) issue subpoenas; and"],[1,"(B) order the taking of depositions and order responses to written interrogatories;"],[0,"in the same manner as provided under section 1204."],[0,"(3)(A) In the case of contumacy or failure to obey a subpoena issued under paragraph (2)(A), the Special Counsel may apply to the Merit Systems Protection Board to enforce the subpoena in court pursuant to section 1204(c)."],[0,"(B) A subpoena under paragraph (2)(A) may, in the case of any individual outside the territorial jurisdiction of any court of the United States, be served in the manner referred to in subsection (d) of section 1204, and the United States District Court for the District of Columbia may, with respect to any such individual, compel compliance in accordance with such subsection."],[0,"(4) Witnesses (whether appearing voluntarily or under subpoena) shall be paid the same fee and mileage allowances which are paid subpoenaed witnesses in the courts of the United States."],[0,"(5)(A) Except as provided in subparagraph (B), the Special Counsel, in carrying out this subchapter, is authorized to—"],[1,"(i) have timely access to all records, data, reports, audits, reviews, documents, papers, recommendations, or other material available to the applicable agency that relate to an investigation, review, or inquiry conducted under—"],[2,"(I) section 1213, 1214, 1215, or 1216 of this title; or"],[2,"(II) section 4324(a) of title 38;"],[1,"(ii) request from any agency the information or assistance that may be necessary for the Special Counsel to carry out the duties and responsibilities of the Special Counsel under this subchapter; and"],[1,"(iii) require, during an investigation, review, or inquiry of an agency, the agency to provide to the Special Counsel any record or other information that relates to an investigation, review, or inquiry conducted under—"],[2,"(I) section 1213, 1214, 1215, or 1216 of this title; or"],[2,"(II) section 4324(a) of title 38."],[0,"(B)(i) The authorization of the Special Counsel under subparagraph (A) shall not apply with respect to any entity that is an element of the intelligence community, as defined in section 3 of the National Security Act of 1947 (50 U.S.C. 3003), unless the Special Counsel is investigating, or otherwise carrying out activities relating to the enforcement of, an action under subchapter III of chapter 73."],[0,"(ii) An Inspector General may withhold from the Special Counsel material described in subparagraph (A) if the Inspector General determines that the material contains information derived from, or pertaining to, intelligence activities."],[0,"(iii) The Attorney General or an Inspector General may withhold from the Special Counsel material described in subparagraph (A) if—"],[1,"(I)(aa) disclosing the material could reasonably be expected to interfere with a criminal investigation or prosecution that is ongoing as of the date on which the Special Counsel submits a request for the material; or"],[1,"(bb) the material—"],[2,"(AA) may not be disclosed pursuant to a court order; or"],[2,"(BB) has been filed under seal under section 3730 of title 31; and"],[1,"(II) the Attorney General or the Inspector General, as applicable, submits to the Special Counsel a written report that describes—"],[2,"(aa) the material being withheld; and"],[2,"(bb) the reason that the material is being withheld."],[0,"(C)(i) A claim of common law privilege by an agency, or an officer or employee of an agency, shall not prevent the Special Counsel from obtaining any material described in subparagraph (A)(i) with respect to the agency."],[0,"(ii) The submission of material described in subparagraph (A)(i) by an agency to the Special Counsel may not be deemed to waive any assertion of privilege by the agency against a non-Federal entity or against an individual in any other proceeding."],[0,"(iii) With respect to any record or other information made available to the Special Counsel by an agency under subparagraph (A), the Special Counsel may only disclose the record or information for a purpose that is in furtherance of any authority provided to the Special Counsel under this subchapter."],[0,"(6) The Special Counsel shall submit to the Committee on Homeland Security and Governmental Affairs of the Senate, the Committee on Oversight and Government Reform of the House of Representatives, and each committee of Congress with jurisdiction over the applicable agency a report regarding any case of contumacy or failure to comply with a request submitted by the Special Counsel under paragraph (5)(A)."],[0,"(c)(1) Except as provided in paragraph (2), the Special Counsel may as a matter of right intervene or otherwise participate in any proceeding before the Merit Systems Protection Board, except that the Special Counsel shall comply with the rules of the Board."],[0,"(2) The Special Counsel may not intervene in an action brought by an individual under section 1221, or in an appeal brought by an individual under section 7701, without the consent of such individual."],[0,"(d)(1) The Special Counsel may appoint the legal, administrative, and support personnel necessary to perform the functions of the Special Counsel."],[0,"(2) Any appointment made under this subsection shall be made in accordance with the provisions of this title, except that such appointment shall not be subject to the approval or supervision of the Office of Personnel Management or the Executive Office of the President (other than approval required under section 3324 or subchapter VIII of chapter 33)."],[0,"(e) The Special Counsel may prescribe such regulations as may be necessary to perform the functions of the Special Counsel. Such regulations shall be published in the Federal Register."],[0,"(f) The Special Counsel may not issue any advisory opinion concerning any law, rule, or regulation (other than an advisory opinion concerning chapter 15 or subchapter III of chapter 73)."],[0,"(g)(1) The Special Counsel may not respond to any inquiry or disclose any information from or about any person making an allegation under section 1214(a), except in accordance with the provisions of section 552a of title 5, United States Code, or as required by any other applicable Federal law."],[0,"(2) Notwithstanding the exception under paragraph (1), the Special Counsel may not respond to any inquiry concerning an evaluation of the work performance, ability, aptitude, general qualifications, character, loyalty, or suitability for any personnel action of any person described in paragraph (1)—"],[1,"(A) unless the consent of the individual as to whom the information pertains is obtained in advance; or"],[1,"(B) except upon request of an agency which requires such information in order to make a determination concerning an individual's having access to the information unauthorized disclosure of which could be expected to cause exceptionally grave damage to the national security."],[0,"(h)(1) The Special Counsel is authorized to appear as amicus curiae in any action brought in a court of the United States related to section 2302(b)(8) or (9), or as otherwise authorized by law. In any such action, the Special Counsel is authorized to present the views of the Special Counsel with respect to compliance with section 2302(b)(8) or (9) and the impact court decisions would have on the enforcement of such provisions of law."],[0,"(2) A court of the United States shall grant the application of the Special Counsel to appear in any such action for the purposes described under subsection (a)."],[0,"(i) The Special Counsel shall enter into at least 1 agreement with the Inspector General of an agency under which—"],[1,"(1) the Inspector General shall—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/1212?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1212. Powers and functions of the Office of Special Counsel","tname":"Government Organization and Employees","by":{"1":"33"}},{"t":"usc","label":"12 U.S.C. § 5561","url":"https://www.law.cornell.edu/uscode/text/12/5561","subs":["(5)"],"by":{"1":"3"}},{"t":"usc","label":"12 U.S.C. § 5565","url":"https://www.law.cornell.edu/uscode/text/12/5565","subs":["(a)","(c)"],"by":{"1":"18, 18","2":"20"}},{"t":"usc","label":"15 U.S.C. § 45","url":"https://www.law.cornell.edu/uscode/text/15/45","subs":["(m)","(a)(2)"],"stext":{"head":"§45. Unfair methods of competition unlawful; prevention by Commission","paras":[[0,"(a) Declaration of unlawfulness; power to prohibit unfair practices; inapplicability to foreign trade"],[0,"(1) Unfair methods of competition in or affecting commerce, and unfair or deceptive acts or practices in or affecting commerce, are hereby declared unlawful."],[0,"(2) The Commission is hereby empowered and directed to prevent persons, partnerships, or corporations, except banks, savings and loan institutions described in section 57a(f)(3) of this title, Federal credit unions described in section 57a(f)(4) of this title, common carriers subject to the Acts to regulate commerce, air carriers and foreign air carriers subject to part A of subtitle VII of title 49, and persons, partnerships, or corporations insofar as they are subject to the Packers and Stockyards Act, 1921, as amended [7 U.S.C. 181 et seq.], except as provided in section 406(b) of said Act [7 U.S.C. 227(b)], from using unfair methods of competition in or affecting commerce and unfair or deceptive acts or practices in or affecting commerce."],[0,"(3) This subsection shall not apply to unfair methods of competition involving commerce with foreign nations (other than import commerce) unless—"],[1,"(A) such methods of competition have a direct, substantial, and reasonably foreseeable effect—"],[2,"(i) on commerce which is not commerce with foreign nations, or on import commerce with foreign nations; or"],[2,"(ii) on export commerce with foreign nations, of a person engaged in such commerce in the United States; and"],[1,"(B) such effect gives rise to a claim under the provisions of this subsection, other than this paragraph."],[0,"If this subsection applies to such methods of competition only because of the operation of subparagraph (A)(ii), this subsection shall apply to such conduct only for injury to export business in the United States."],[0,"(4)(A) For purposes of subsection (a), the term \"unfair or deceptive acts or practices\" includes such acts or practices involving foreign commerce that—"],[1,"(i) cause or are likely to cause reasonably foreseeable injury within the United States; or"],[1,"(ii) involve material conduct occurring within the United States."],[0,"(B) All remedies available to the Commission with respect to unfair and deceptive acts or practices shall be available for acts and practices described in this paragraph, including restitution to domestic or foreign victims."],[0,"(b) Proceeding by Commission; modifying and setting aside orders"],[0,"Whenever the Commission shall have reason to believe that any such person, partnership, or corporation has been or is using any unfair method of competition or unfair or deceptive act or practice in or affecting commerce, and if it shall appear to the Commission that a proceeding by it in respect thereof would be to the interest of the public, it shall issue and serve upon such person, partnership, or corporation a complaint stating its charges in that respect and containing a notice of a hearing upon a day and at a place therein fixed at least thirty days after the service of said complaint. The person, partnership, or corporation so complained of shall have the right to appear at the place and time so fixed and show cause why an order should not be entered by the Commission requiring such person, partnership, or corporation to cease and desist from the violation of the law so charged in said complaint. Any person, partnership, or corporation may make application, and upon good cause shown may be allowed by the Commission to intervene and appear in said proceeding by counsel or in person. The testimony in any such proceeding shall be reduced to writing and filed in the office of the Commission. If upon such hearing the Commission shall be of the opinion that the method of competition or the act or practice in question is prohibited by this subchapter, it shall make a report in writing in which it shall state its findings as to the facts and shall issue and cause to be served on such person, partnership, or corporation an order requiring such person, partnership, or corporation to cease and desist from using such method of competition or such act or practice. Until the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, or, if a petition for review has been filed within such time then until the record in the proceeding has been filed in a court of appeals of the United States, as hereinafter provided, the Commission may at any time, upon such notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any report or any order made or issued by it under this section. After the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, the Commission may at any time, after notice and opportunity for hearing, reopen and alter, modify, or set aside, in whole or in part any report or order made or issued by it under this section, whenever in the opinion of the Commission conditions of fact or of law have so changed as to require such action or if the public interest shall so require, except that (1) the said person, partnership, or corporation may, within sixty days after service upon him or it of said report or order entered after such a reopening, obtain a review thereof in the appropriate court of appeals of the United States, in the manner provided in subsection (c) of this section; and (2) in the case of an order, the Commission shall reopen any such order to consider whether such order (including any affirmative relief provision contained in such order) should be altered, modified, or set aside, in whole or in part, if the person, partnership, or corporation involved files a request with the Commission which makes a satisfactory showing that changed conditions of law or fact require such order to be altered, modified, or set aside, in whole or in part. The Commission shall determine whether to alter, modify, or set aside any order of the Commission in response to a request made by a person, partnership, or corporation under paragraph 1 (2) not later than 120 days after the date of the filing of such request."],[0,"(c) Review of order; rehearing"],[0,"Any person, partnership, or corporation required by an order of the Commission to cease and desist from using any method of competition or act or practice may obtain a review of such order in the court of appeals of the United States, within any circuit where the method of competition or the act or practice in question was used or where such person, partnership, or corporation resides or carries on business, by filing in the court, within sixty days from the date of the service of such order, a written petition praying that the order of the Commission be set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Commission, and thereupon the Commission shall file in the court the record in the proceeding, as provided in section 2112 of title 28. Upon such filing of the petition the court shall have jurisdiction of the proceeding and of the question determined therein concurrently with the Commission until the filing of the record and shall have power to make and enter a decree affirming, modifying, or setting aside the order of the Commission, and enforcing the same to the extent that such order is affirmed and to issue such writs as are ancillary to its jurisdiction or are necessary in its judgement to prevent injury to the public or to competitors pendente lite. The findings of the Commission as to the facts, if supported by evidence, shall be conclusive. To the extent that the order of the Commission is affirmed, the court shall thereupon issue its own order commanding obedience to the terms of such order of the Commission. If either party shall apply to the court for leave to adduce additional evidence, and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Commission, the court may order such additional evidence to be taken before the Commission and to be adduced upon the hearing in such manner and upon such terms and conditions as to the court may seem proper. The Commission may modify its findings as to the facts, or make new findings, by reason of the additional evidence so taken, and it shall file such modified or new findings, which, if supported by evidence, shall be conclusive, and its recommendation, if any, for the modification or setting aside of its original order, with the return of such additional evidence. The judgment and decree of the court shall be final, except that the same shall be subject to review by the Supreme Court upon certiorari, as provided in section 1254 of title 28."],[0,"(d) Jurisdiction of court"],[0,"Upon the filing of the record with it the jurisdiction of the court of appeals of the United States to affirm, enforce, modify, or set aside orders of the Commission shall be exclusive."],[0,"(e) Exemption from liability"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/45?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§45. Unfair methods of competition unlawful; prevention by Commission","tname":"Commerce and Trade","by":{"1":"32","2":"20, 20"}},{"t":"law","label":"Pub. L. No. 107-204","url":"https://www.govinfo.gov/link/plaw/107/public/204","by":{"1":"23"}},{"t":"law","label":"Pub. L. No. 103-296","url":"https://www.govinfo.gov/link/statute/108/1466","by":{"1":"34"}},{"t":"usc","label":"3 U.S.C. § 19","url":"https://www.law.cornell.edu/uscode/text/3/19","by":{"1":"38"}},{"t":"usc","label":"12 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/12/2","stext":{"head":"§2. Comptroller of the Currency; appointment; term","paras":[[0,"The Comptroller of the Currency shall be appointed by the President, by and with the advice and consent of the Senate, and shall hold his office for a term of five years unless sooner removed by the President, upon reasons to be communicated by him to the Senate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/2?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§2. Comptroller of the Currency; appointment; term","tname":"Banks and Banking","by":{"1":"42, 43"}},{"t":"usc","label":"12 U.S.C. § 4511","url":"https://www.law.cornell.edu/uscode/text/12/4511","by":{"1":"34"}},{"t":"usc","label":"12 U.S.C. § 4512","url":"https://www.law.cornell.edu/uscode/text/12/4512","by":{"1":"34"}},{"t":"reg","label":"12 C.F.R. § 1083.1","url":"https://www.ecfr.gov/current/title-12/section-1083.1","by":{"1":"3"}},{"t":"case","label":"Advanced Disposal Servs. E., Inc. v. NLRB","cite":"820 F.3d 592","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/820/592/","by":{"2":"7"}},{"t":"case","label":"Ashwander v. TVA","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"sum":"The Court held that Congress did not abuse its power with the TVA. Justice Hughes argued that the Wilson Dam, the location where the TVA was in the business of generating electricity, had been built originally in the interest of national defense: it produced materials involved in munitions manufacture. The government could sell excess electricity to consumers without violating the Constitution.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Blake v. United States","cite":"103 U.S. 227","y":1880,"id":"scdb/1880-146","sc":1,"sum":"This suit was instituted in the Court of Claims, by Blake, to recover the amount claimed to'-be due him, by way of salary as a post-chaplain in the army, from April 28, 1869, to May 14, 1878.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"CFPB v. Gordon","cite":"819 F.3d 1179","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/819/1179/","by":{"2":"7"}},{"t":"case","label":"Exec. Benefits Ins. Agency v. Arkison","cite":"573 U.S. 25","y":2014,"id":"2013/12-1200","sc":1,"sum":"The Court found that a bankruptcy judge may hear arguments and file a report with a district court for \"non-core\" bankruptcy issues.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"FEC v. Legi-Tech, Inc.","cite":"75 F.3d 704","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/75/704/","by":{"2":"7"}},{"t":"case","label":"Gamble v. United States","cite":"139 S. Ct. 1960","y":2019,"id":"2018/17-646","sc":1,"op":2,"sum":"The dual sovereignty doctrine—under which two offenses are not the “same offence” for double jeopardy purposes if prosecuted by separate sovereigns—is upheld.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"31"}},{"t":"case","label":"Guedes v. ATF","cite":"920 F.3d 1","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/920/1/","by":{"2":"7"}},{"t":"case","label":"Heckler v. Mathews","cite":"465 U.S. 728","y":1984,"id":"1983/82-1050","sc":1,"sum":"The unanimous Court upheld the law. Justice Brennan granted that the 1977 amendments temporarily revived gender-based eligibility requirements, but maintained that they served a legitimate government interest, namely, they protected individuals who had planned for their retirements relying on the law as it stood before the Court's Califano decision.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Hubbard v. United States","cite":"514 U.S. 695","y":1995,"id":"1994/94-172","sc":1,"sum":"The judgment is reversed in part. 16 F. 3d 694, reversed in part. JUSTICE STEVENS delivered the opinion of the Court with respect to Parts I, II, III, and VI, concluding that, because a federal court is neither a \"department\" nor an \"agency\" within § 1001's meaning, the statute does not apply to false statements made in judicial proceedings. Pp. 699-708, 715.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Kimble v. Marvel Entmt., LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Nw. Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"United States v. Windsor","cite":"570 U.S. 744","y":2013,"id":"2012/12-307","sc":1,"op":2,"ar":3,"sum":"The Court found that the Defense of Marriage Act (DOMA) was unconstitutional under the equal protection clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"2":"13","3":"5"}},{"t":"const","label":"Article I, Section 8","by":{"2":"14"}},{"t":"usc","label":"12 U.S.C. § 5512","url":"https://www.law.cornell.edu/uscode/text/12/5512","stext":{"head":"§5512. Rulemaking authority","paras":[[0,"(a) In general"],[0,"The Bureau is authorized to exercise its authorities under Federal consumer financial law to administer, enforce, and otherwise implement the provisions of Federal consumer financial law."],[0,"(b) Rulemaking, orders, and guidance"],[0,"(1) General authority"],[1,"The Director may prescribe rules and issue orders and guidance, as may be necessary or appropriate to enable the Bureau to administer and carry out the purposes and objectives of the Federal consumer financial laws, and to prevent evasions thereof."],[0,"(2) Standards for rulemaking"],[1,"In prescribing a rule under the Federal consumer financial laws—"],[2,"(A) the Bureau shall consider—"],[3,"(i) the potential benefits and costs to consumers and covered persons, including the potential reduction of access by consumers to consumer financial products or services resulting from such rule; and"],[3,"(ii) the impact of proposed rules on covered persons, as described in section 5516 of this title, and the impact on consumers in rural areas;"],[2,"(B) the Bureau shall consult with the appropriate prudential regulators or other Federal agencies prior to proposing a rule and during the comment process regarding consistency with prudential, market, or systemic objectives administered by such agencies; and"],[2,"(C) if, during the consultation process described in subparagraph (B), a prudential regulator provides the Bureau with a written objection to the proposed rule of the Bureau or a portion thereof, the Bureau shall include in the adopting release a description of the objection and the basis for the Bureau decision, if any, regarding such objection, except that nothing in this clause shall be construed as altering or limiting the procedures under section 5513 of this title that may apply to any rule prescribed by the Bureau."],[0,"(3) Exemptions"],[0,"(A) In general"],[2,"The Bureau, by rule, may conditionally or unconditionally exempt any class of covered persons, service providers, or consumer financial products or services, from any provision of this title,1 or from any rule issued under this title,1 as the Bureau determines necessary or appropriate to carry out the purposes and objectives of this title,1 taking into consideration the factors in subparagraph (B)."],[0,"(B) Factors"],[2,"In issuing an exemption, as permitted under subparagraph (A), the Bureau shall, as appropriate, take into consideration—"],[3,"(i) the total assets of the class of covered persons;"],[3,"(ii) the volume of transactions involving consumer financial products or services in which the class of covered persons engages; and"],[3,"(iii) existing provisions of law which are applicable to the consumer financial product or service and the extent to which such provisions provide consumers with adequate protections."],[0,"(4) Exclusive rulemaking authority"],[0,"(A) In general"],[2,"Notwithstanding any other provisions of Federal law and except as provided in section 5581(b)(5) of this title, to the extent that a provision of Federal consumer financial law authorizes the Bureau and another Federal agency to issue regulations under that provision of law for purposes of assuring compliance with Federal consumer financial law and any regulations thereunder, the Bureau shall have the exclusive authority to prescribe rules subject to those provisions of law."],[0,"(B) Deference"],[2,"Notwithstanding any power granted to any Federal agency or to the Council under this title,1 and subject to section 5581(b)(5)(E) of this title, the deference that a court affords to the Bureau with respect to a determination by the Bureau regarding the meaning or interpretation of any provision of a Federal consumer financial law shall be applied as if the Bureau were the only agency authorized to apply, enforce, interpret, or administer the provisions of such Federal consumer financial law."],[0,"(c) Monitoring"],[0,"(1) In general"],[1,"In order to support its rulemaking and other functions, the Bureau shall monitor for risks to consumers in the offering or provision of consumer financial products or services, including developments in markets for such products or services."],[0,"(2) Considerations"],[1,"In allocating its resources to perform the monitoring required by this section, the Bureau may consider, among other factors—"],[2,"(A) likely risks and costs to consumers associated with buying or using a type of consumer financial product or service;"],[2,"(B) understanding by consumers of the risks of a type of consumer financial product or service;"],[2,"(C) the legal protections applicable to the offering or provision of a consumer financial product or service, including the extent to which the law is likely to adequately protect consumers;"],[2,"(D) rates of growth in the offering or provision of a consumer financial product or service;"],[2,"(E) the extent, if any, to which the risks of a consumer financial product or service may disproportionately affect traditionally underserved consumers; or"],[2,"(F) the types, number, and other pertinent characteristics of covered persons that offer or provide the consumer financial product or service."],[0,"(3) Significant findings"],[0,"(A) In general"],[2,"The Bureau shall publish not fewer than 1 report of significant findings of its monitoring required by this subsection in each calendar year, beginning with the first calendar year that begins at least 1 year after the designated transfer date."],[0,"(B) Confidential information"],[2,"The Bureau may make public such information obtained by the Bureau under this section as is in the public interest, through aggregated reports or other appropriate formats designed to protect confidential information in accordance with paragraphs (4), (6), (8), and (9)."],[0,"(4) Collection of information"],[0,"(A) In general"],[2,"In conducting any monitoring or assessment required by this section, the Bureau shall have the authority to gather information from time to time regarding the organization, business conduct, markets, and activities of covered persons and service providers."],[0,"(B) Methodology"],[2,"In order to gather information described in subparagraph (A), the Bureau may—"],[3,"(i) gather and compile information from a variety of sources, including examination reports concerning covered persons or service providers, consumer complaints, voluntary surveys and voluntary interviews of consumers, surveys and interviews with covered persons and service providers, and review of available databases; and"],[3,"(ii) require covered persons and service providers participating in consumer financial services markets to file with the Bureau, under oath or otherwise, in such form and within such reasonable period of time as the Bureau may prescribe by rule or order, annual or special reports, or answers in writing to specific questions, furnishing information described in paragraph (4), as necessary for the Bureau to fulfill the monitoring, assessment, and reporting responsibilities imposed by Congress."],[0,"(C) Limitation"],[2,"The Bureau may not use its authorities under this paragraph to obtain records from covered persons and service providers participating in consumer financial services markets for purposes of gathering or analyzing the personally identifiable financial information of consumers."],[0,"(5) Limited information gathering"],[1,"In order to assess whether a nondepository is a covered person, as defined in section 5481 of this title, the Bureau may require such nondepository to file with the Bureau, under oath or otherwise, in such form and within such reasonable period of time as the Bureau may prescribe by rule or order, annual or special reports, or answers in writing to specific questions."],[0,"(6) Confidentiality rules"],[0,"(A) Rulemaking"],[2,"The Bureau shall prescribe rules regarding the confidential treatment of information obtained from persons in connection with the exercise of its authorities under Federal consumer financial law."],[0,"(B) Access by the Bureau to reports of other regulators"],[0,"(i) Examination and financial condition reports"],[3,"Upon providing reasonable assurances of confidentiality, the Bureau shall have access to any report of examination or financial condition made by a prudential regulator or other Federal agency having jurisdiction over a covered person or service provider, and to all revisions made to any such report."],[0,"(ii) Provision of other reports to the Bureau"],[3,"In addition to the reports described in clause (i), a prudential regulator or other Federal agency having jurisdiction over a covered person or service provider may, in its discretion, furnish to the Bureau any other report or other confidential supervisory information concerning any insured depository institution, credit union, or other entity examined by such agency under authority of any provision of Federal law."],[0,"(C) Access by other regulators to reports of the Bureau"],[0,"(i) Examination reports"],[3,"Upon providing reasonable assurances of confidentiality, a prudential regulator, a State regulator, or any other Federal agency having jurisdiction over a covered person or service provider shall have access to any report of examination made by the Bureau with respect to such person, and to all revisions made to any such report."],[0,"(ii) Provision of other reports to other regulators"],[3,"In addition to the reports described in clause (i), the Bureau may, in its discretion, furnish to a prudential regulator or other agency having jurisdiction over a covered person or service provider any other report or other confidential supervisory information concerning such person examined by the Bureau under the authority of any other provision of Federal law."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5512?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5512. Rulemaking authority","tname":"Banks and Banking","by":{"2":"20"}},{"t":"usc","label":"12 U.S.C. § 5563","url":"https://www.law.cornell.edu/uscode/text/12/5563","stext":{"head":"§5563. Hearings and adjudication proceedings","paras":[[0,"(a) In general"],[0,"The Bureau is authorized to conduct hearings and adjudication proceedings with respect to any person in the manner prescribed by chapter 5 of title 5 in order to ensure or enforce compliance with—"],[1,"(1) the provisions of this title,1 including any rules prescribed by the Bureau under this title; 1 and"],[1,"(2) any other Federal law that the Bureau is authorized to enforce, including an enumerated consumer law, and any regulations or order prescribed thereunder, unless such Federal law specifically limits the Bureau from conducting a hearing or adjudication proceeding and only to the extent of such limitation."],[0,"(b) Special rules for cease-and-desist proceedings"],[0,"(1) Orders authorized"],[0,"(A) In general"],[2,"If, in the opinion of the Bureau, any covered person or service provider is engaging or has engaged in an activity that violates a law, rule, or any condition imposed in writing on the person by the Bureau, the Bureau may, subject to sections 5514, 5515, and 5516 of this title, issue and serve upon the covered person or service provider a notice of charges in respect thereof."],[0,"(B) Content of notice"],[2,"The notice under subparagraph (A) shall contain a statement of the facts constituting the alleged violation or violations, and shall fix a time and place at which a hearing will be held to determine whether an order to cease and desist should issue against the covered person or service provider, such hearing to be held not earlier than 30 days nor later than 60 days after the date of service of such notice, unless an earlier or a later date is set by the Bureau, at the request of any party so served."],[0,"(C) Consent"],[2,"Unless the party or parties served under subparagraph (B) appear at the hearing personally or by a duly authorized representative, such person shall be deemed to have consented to the issuance of the cease-and-desist order."],[0,"(D) Procedure"],[2,"In the event of consent under subparagraph (C), or if, upon the record, made at any such hearing, the Bureau finds that any violation specified in the notice of charges has been established, the Bureau may issue and serve upon the covered person or service provider an order to cease and desist from the violation or practice. Such order may, by provisions which may be mandatory or otherwise, require the covered person or service provider to cease and desist from the subject activity, and to take affirmative action to correct the conditions resulting from any such violation."],[0,"(2) Effectiveness of order"],[1,"A cease-and-desist order shall become effective at the expiration of 30 days after the date of service of an order under paragraph (1) upon the covered person or service provider concerned (except in the case of a cease-and-desist order issued upon consent, which shall become effective at the time specified therein), and shall remain effective and enforceable as provided therein, except to such extent as the order is stayed, modified, terminated, or set aside by action of the Bureau or a reviewing court."],[0,"(3) Decision and appeal"],[1,"Any hearing provided for in this subsection shall be held in the Federal judicial district or in the territory in which the residence or principal office or place of business of the person is located unless the person consents to another place, and shall be conducted in accordance with the provisions of chapter 5 of title 5. After such hearing, and within 90 days after the Bureau has notified the parties that the case has been submitted to the Bureau for final decision, the Bureau shall render its decision (which shall include findings of fact upon which its decision is predicated) and shall issue and serve upon each party to the proceeding an order or orders consistent with the provisions of this section. Judicial review of any such order shall be exclusively as provided in this subsection. Unless a petition for review is timely filed in a court of appeals of the United States, as provided in paragraph (4), and thereafter until the record in the proceeding has been filed as provided in paragraph (4), the Bureau may at any time, upon such notice and in such manner as the Bureau shall determine proper, modify, terminate, or set aside any such order. Upon filing of the record as provided, the Bureau may modify, terminate, or set aside any such order with permission of the court."],[0,"(4) Appeal to court of appeals"],[1,"Any party to any proceeding under this subsection may obtain a review of any order served pursuant to this subsection (other than an order issued with the consent of the person concerned) by the filing in the court of appeals of the United States for the circuit in which the principal office of the covered person is located, or in the United States Court of Appeals for the District of Columbia Circuit, within 30 days after the date of service of such order, a written petition praying that the order of the Bureau be modified, terminated, or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Bureau, and thereupon the Bureau shall file in the court the record in the proceeding, as provided in section 2112 of title 28. Upon the filing of such petition, such court shall have jurisdiction, which upon the filing of the record shall except as provided in the last sentence of paragraph (3) be exclusive, to affirm, modify, terminate, or set aside, in whole or in part, the order of the Bureau. Review of such proceedings shall be had as provided in chapter 7 of title 5. The judgment and decree of the court shall be final, except that the same shall be subject to review by the Supreme Court of the United States, upon certiorari, as provided in section 1254 of title 28."],[0,"(5) No stay"],[1,"The commencement of proceedings for judicial review under paragraph (4) shall not, unless specifically ordered by the court, operate as a stay of any order issued by the Bureau."],[0,"(c) Special rules for temporary cease-and-desist proceedings"],[0,"(1) In general"],[1,"Whenever the Bureau determines that the violation specified in the notice of charges served upon a person, including a service provider, pursuant to subsection (b), or the continuation thereof, is likely to cause the person to be insolvent or otherwise prejudice the interests of consumers before the completion of the proceedings conducted pursuant to subsection (b), the Bureau may issue a temporary order requiring the person to cease and desist from any such violation or practice and to take affirmative action to prevent or remedy such insolvency or other condition pending completion of such proceedings. Such order may include any requirement authorized under this part. Such order shall become effective upon service upon the person and, unless set aside, limited, or suspended by a court in proceedings authorized by paragraph (2), shall remain effective and enforceable pending the completion of the administrative proceedings pursuant to such notice and until such time as the Bureau shall dismiss the charges specified in such notice, or if a cease-and-desist order is issued against the person, until the effective date of such order."],[0,"(2) Appeal"],[1,"Not later than 10 days after the covered person or service provider concerned has been served with a temporary cease-and-desist order, the person may apply to the United States district court for the judicial district in which the residence or principal office or place of business of the person is located, or the United States District Court for the District of Columbia, for an injunction setting aside, limiting, or suspending the enforcement, operation, or effectiveness of such order pending the completion of the administrative proceedings pursuant to the notice of charges served upon the person under subsection (b), and such court shall have jurisdiction to issue such injunction."],[0,"(3) Incomplete or inaccurate records"],[0,"(A) Temporary order"],[2,"If a notice of charges served under subsection (b) specifies, on the basis of particular facts and circumstances, that the books and records of a covered person or service provider are so incomplete or inaccurate that the Bureau is unable to determine the financial condition of that person or the details or purpose of any transaction or transactions that may have a material effect on the financial condition of that person, the Bureau may issue a temporary order requiring—"],[3,"(i) the cessation of any activity or practice which gave rise, whether in whole or in part, to the incomplete or inaccurate state of the books or records; or"],[3,"(ii) affirmative action to restore such books or records to a complete and accurate state, until the completion of the proceedings under subsection (b)(1)."],[0,"(B) Effective period"],[2,"Any temporary order issued under subparagraph (A)—"],[3,"(i) shall become effective upon service; and"],[3,"(ii) unless set aside, limited, or suspended by a court in proceedings under paragraph (2), shall remain in effect and enforceable until the earlier of—"],[4,"(I) the completion of the proceeding initiated under subsection (b) in connection with the notice of charges; or"],[4,"(II) the date the Bureau determines, by examination or otherwise, that the books and records of the covered person or service provider are accurate and reflect the financial condition thereof."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5563?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5563. Hearings and adjudication proceedings","tname":"Banks and Banking","by":{"2":"20"}},{"t":"usc","label":"12 U.S.C. § 5586","url":"https://www.law.cornell.edu/uscode/text/12/5586","subs":["(a)"],"by":{"2":"12"}},{"t":"usc","label":"5 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/5/1202","subs":["(d)"],"by":{"2":"31"}},{"t":"usc","label":"12 U.S.C. § 242","url":"https://www.law.cornell.edu/uscode/text/12/242","by":{"2":"31"}},{"t":"usc","label":"15 U.S.C. § 53","url":"https://www.law.cornell.edu/uscode/text/15/53","by":{"2":"20"}},{"t":"usc","label":"15 U.S.C. § 57a","url":"https://www.law.cornell.edu/uscode/text/15/57a","by":{"2":"20"}},{"t":"usc","label":"15 U.S.C. § 57b-3","url":"https://www.law.cornell.edu/uscode/text/15/57b-3","by":{"2":"20"}},{"t":"case","label":"Bond v. United States","cite":"564 U.S. 211","y":2011,"id":"2010/09-1227","sc":1,"op":1,"sum":"The Court held that a defendant, convicted under a federal statute, has a right to challenge his/her conviction based on the unconstitutionality of the statute.","sumSrc":"Oyez","by":{"3":"4, 5, 6"}},{"t":"case","label":"CFPB v. RD Legal Funding, LLC","cite":"332 F. Supp. 3d 729","y":2018,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/332/729/","by":{"3":"19"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Hudson v. United States","cite":"522 U.S. 93","y":1997,"id":"1997/96-976","sc":1,"sum":"The Court held that the Double Jeopardy Clause does not apply to non-criminal penalties, even if the purpose of the penalty is to punish the offenders and deter future offenders. Since the first punishment handed down by the OCC - a Federal Banking Agency, not a court - was not a criminal punishment, the subsequent indictments were upheld.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":1,"sum":"Explaining that the plaintiff 's injury must be “fairly traceable to the challenged action of the defendant” (internal quotation marks and alterations 1 Director Kraninger did not indicate whether she would disregard her statutory removal protection if the President attempted to remove her without cause. omitted).","sumSrc":"opinion","by":{"3":"4"}},{"t":"case","label":"Shurtleff v. United States","cite":"189 U.S. 311","y":1903,"id":"scdb/1902-126","sc":1,"sum":"Where Congress creates an office and provides for the removal of the incumbent at any time for inefficiency, neglect of duty, or malfeasance in office, if the removal of the officer is sought to be made for any of those causes he is entitled to notice and a hearing; but if the President removes him without giving him notice and an opportunity to defend himself, it must be presumed that the removal was not made for …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Summers v. Earth Island Institute","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"United States v. Halper","cite":"490 U.S. 435","y":1989,"id":"1988/87-1383","sc":1,"sum":"Justice Harry Blackmun, on behalf of a unanimous Supreme Court, wrote that while previous cases had held penalties under the Act to be civil in nature, that did not foreclose the possibility of the penalty being so extreme and so unrelated to the actual damages as to constitute \"punishment.\" Because Halper had already been jailed and fined, additional punishment in a separate proceeding would violate the Double Jeopardy Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"const","label":"Article II, Section 4","clauses":[["impeachment","Impeachment"]],"text":"The President, Vice President and all civil Officers of the United States, shall be removed from Office on Impeachment for, and Conviction of, Treason, Bribery, or other high Crimes and Misdemeanors.","by":{"3":"12"}}]};